.plaza-net-lab{--pn-bg:#f8f6f1;--pn-text:#45413b;--pn-muted:#7a756b;--pn-line:rgba(145,119,71,.25);--pn-gold:var(--gold,#B2945F)}
[data-theme="dark"] .plaza-net-lab{--pn-bg:#252723;--pn-text:#eee9df;--pn-muted:#b1ad9e;--pn-line:rgba(212,171,104,.25);--pn-gold:#d4ab68}
.plaza-net-lab .site-header{z-index:1100;isolation:isolate}
.plaza-net-lab .header-inner{display:flex!important;flex-wrap:nowrap!important;align-items:center;gap:20px;padding-block:12px!important;min-height:76px}
.plaza-net-lab .site-header .brand{flex:0 0 188px;margin:0}.plaza-net-lab .site-header .brand svg{display:block;width:188px!important;height:42px!important}
.plaza-net-lab .pn-logo-orbit{transform-box:fill-box;transform-origin:center;animation:pn-logo-spin 3s linear infinite;animation-play-state:paused}.plaza-net-lab .brand:is(:hover,:focus-visible) .pn-logo-orbit{animation-play-state:running}@keyframes pn-logo-spin{to{transform:rotate(360deg)}}
.plaza-net-lab .pn-toggle{display:flex;align-items:center;justify-content:space-between;gap:12px;width:188px;flex:0 0 188px;min-height:48px;padding:3px 0 3px 20px;background:none;border:0;border-left:1px solid var(--pn-line);border-radius:0;color:var(--pn-text);font-family:Montserrat,sans-serif;box-shadow:none;text-align:left;cursor:pointer}
.plaza-net-lab .pn-current{display:flex;flex-direction:column;gap:4px}.plaza-net-lab .pn-current strong{font:500 18px/1.25 Montserrat,sans-serif;letter-spacing:.2px;white-space:nowrap}.plaza-net-lab .pn-current small{font:400 10px/1.4 Montserrat,sans-serif;letter-spacing:1px;text-transform:none;color:var(--pn-muted)}
.plaza-net-lab .pn-mark{display:block;width:10px;height:10px;margin-right:3px;border-right:1.5px solid var(--pn-gold);border-bottom:1.5px solid var(--pn-gold);transform:translateY(-3px) rotate(45deg);transition:transform .4s ease}.plaza-net-lab .pn-toggle[aria-expanded="true"] .pn-mark{transform:translateY(3px) rotate(225deg)}
.plaza-net-lab .site-nav{display:flex!important;position:static!important;width:auto!important;order:initial;margin:0 0 0 auto!important;padding:0!important;border:0!important;box-shadow:none!important;background:none!important;align-items:center;gap:16px;flex:0 0 auto}
.plaza-net-lab .site-nav .nav-links{display:flex!important;flex-direction:row!important;align-items:center;gap:22px;margin:0!important;padding:0!important}.plaza-net-lab .nav-links a{font:400 12px/1.4 Montserrat,sans-serif;letter-spacing:0;white-space:nowrap;padding:14px 0!important}
.plaza-net-lab .mobile-nav-extra,.plaza-net-lab .header-actions .menu-toggle{display:none!important}.plaza-net-lab .header-actions{margin:0!important;gap:14px;flex:0 0 auto}.plaza-net-lab .header-call span{display:none!important}.plaza-net-lab .header-call{width:36px;min-height:44px;justify-content:center}.plaza-net-lab .header-price{font-size:11px!important;padding:12px 14px!important;white-space:nowrap}
.plaza-net-lab .pn-burger{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:5px;width:44px;height:44px;padding:10px;border:0;border-radius:var(--plaza-radius-ui,4px);background:none;color:var(--pn-gold);box-shadow:none;cursor:pointer;flex:0 0 44px}.plaza-net-lab .pn-burger span{display:block;width:22px;height:1.5px;background:currentColor;transform-origin:center;transition:transform .4s cubic-bezier(.16,1,.3,1),opacity .25s}.plaza-net-lab .pn-burger[aria-expanded="true"] span:nth-child(1){transform:translateY(6.5px) rotate(45deg)}.plaza-net-lab .pn-burger[aria-expanded="true"] span:nth-child(2){opacity:0;transform:scaleX(.5)}.plaza-net-lab .pn-burger[aria-expanded="true"] span:nth-child(3){transform:translateY(-6.5px) rotate(-45deg)}
.plaza-net-lab :is(.pn-toggle,.pn-burger,.pn-select,.pn-city):focus-visible{outline:2px solid var(--pn-gold);outline-offset:4px}
.plaza-net-lab .pn-backdrop{position:fixed;inset:0;z-index:1080;background:transparent;opacity:0;visibility:hidden;transition:opacity .6s ease,visibility .6s,-webkit-backdrop-filter .6s ease,backdrop-filter .6s ease}.plaza-net-lab.pn-open .pn-backdrop{opacity:1;visibility:visible}
/* Both header menus: 300ms opacity fade below the unchanged header, no curtain movement. */
.plaza-net-lab:is(.plaza-object-zheleznovodsk,.plaza-object-kislovodsk,.plaza-object-plaza) .pn-backdrop{top:var(--pn-top,76px);clip-path:none;animation:none;transition:opacity .3s ease,visibility 0s linear .3s}
.plaza-net-lab:is(.plaza-object-zheleznovodsk,.plaza-object-kislovodsk,.plaza-object-plaza).pn-open .pn-backdrop{transition:opacity .3s ease,visibility 0s}

.plaza-net-lab .pn-panel{box-sizing:border-box;position:fixed;top:var(--pn-top,76px);left:0;right:0;z-index:1090;background:var(--pn-bg);color:var(--pn-text);border-top:1px solid var(--pn-line);border-bottom:1px solid var(--pn-line);box-shadow:0 24px 36px rgba(0,0,0,.12);padding:28px max(24px,calc((100vw - 1200px)/2));max-height:calc(100dvh - var(--pn-top,76px));overflow:auto;overscroll-behavior:contain;visibility:hidden;opacity:0;transform:translateY(-12px);transition:opacity .4s ease,transform .5s cubic-bezier(.16,1,.3,1),visibility .5s}.plaza-net-lab .pn-panel[aria-hidden="false"]{visibility:visible;opacity:1;transform:none}
.plaza-net-lab .pn-heading{display:flex;align-items:baseline;justify-content:space-between;gap:24px;margin-bottom:22px}.plaza-net-lab .pn-heading h2{font:400 27px/1.3 Lora,serif;margin:0}.plaza-net-lab .pn-heading p{font:400 11px/1.5 Montserrat,sans-serif;letter-spacing:.5px;color:var(--pn-muted);margin:0}
.plaza-net-lab .pn-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));max-width:900px;margin-inline:auto;gap:20px}.plaza-net-lab .pn-card{position:relative;min-width:0;padding:5px;border:1px solid transparent;border-radius:var(--plaza-radius-ui,4px);background:none;color:var(--pn-text);isolation:isolate;overflow:hidden}.plaza-net-lab .pn-card[data-selected="true"]{border-color:var(--pn-gold)}
.plaza-net-lab .pn-card:before{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(178,148,95,.16),rgba(178,148,95,.04) 32%,transparent 65%);opacity:0;transition:opacity .65s ease;z-index:-1;pointer-events:none}.plaza-net-lab .pn-card:focus-within:before{opacity:1}
.plaza-net-lab .pn-photo{display:block;position:relative;aspect-ratio:1.5;overflow:hidden;border-radius:var(--plaza-radius-ui,4px);background:#dedbd1}.plaza-net-lab .pn-photo img{display:block;position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;transform:none!important;filter:none;transition:opacity .75s ease}.plaza-net-lab .pn-night{opacity:0}[data-theme="dark"] .plaza-net-lab .pn-night{opacity:1}
.plaza-net-lab .pn-caption{padding:12px 8px 8px}.plaza-net-lab .pn-title-row{display:flex;justify-content:space-between;align-items:center;gap:8px}.plaza-net-lab .pn-card-title{font:400 19px/1.4 Lora,serif;margin:0;letter-spacing:0;white-space:nowrap}
.plaza-net-lab .pn-select{display:inline-flex;justify-content:center;align-items:center;min-height:44px;min-width:64px;padding:7px 9px;border:1px solid var(--pn-line);border-radius:var(--plaza-radius-ui,4px);background:transparent;color:var(--pn-text);font:400 12px/1.3 Montserrat,sans-serif;letter-spacing:.15px;box-shadow:none;cursor:pointer}.plaza-net-lab .pn-select[aria-pressed="true"]{background:rgba(178,148,95,.09);border-color:var(--pn-gold)}
.plaza-net-lab .pn-city{display:inline-flex;align-items:center;gap:6px;min-height:44px;color:var(--pn-muted);font:400 11px/1.4 Montserrat,sans-serif;letter-spacing:.2px;text-transform:none;text-decoration:none!important}.plaza-net-lab .pn-city svg{width:14px;height:16px;flex:0 0 auto;color:var(--pn-gold)}.plaza-net-lab a.pn-city span{position:relative}.plaza-net-lab a.pn-city span:after{content:'';position:absolute;bottom:-4px;left:0;right:0;height:1px;background:currentColor;transform:scaleX(0);transform-origin:left;transition:transform .4s}.plaza-net-lab a.pn-city:is(:hover,:focus-visible) span:after{transform:scaleX(1)}
.plaza-net-lab .pn-soon-card .pn-photo{opacity:.42;filter:saturate(.35)}.plaza-net-lab .pn-soon-card .pn-card-title{color:var(--pn-muted)}.plaza-net-lab .pn-select:disabled{cursor:default;color:var(--pn-muted);opacity:.65}.plaza-net-lab .pn-soon{position:absolute;top:14px;left:14px;padding:6px 10px;border-radius:var(--plaza-radius-ui,4px);background:var(--pn-bg);color:var(--pn-muted);font:400 10px/1.3 Montserrat,sans-serif;letter-spacing:.3px}
.plaza-net-lab .pn-menu-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:24px}.plaza-net-lab .pn-menu-grid .footer-nav-group{margin:0;padding:0}.plaza-net-lab .pn-menu-grid h3{font:400 18px/1.4 Lora,serif;margin:0 0 12px;color:var(--pn-gold)}.plaza-net-lab .pn-menu-grid ul{display:block;margin:0;padding:0;list-style:none}.plaza-net-lab .pn-menu-grid li{margin:0;padding:0}.plaza-net-lab .pn-menu-grid a{display:inline-block;box-sizing:border-box;color:var(--pn-text);font:400 11px/1.5 Montserrat,sans-serif;min-height:36px;padding:8px 0;text-decoration:none}.plaza-net-lab .pn-menu-grid a:hover{color:var(--pn-gold)}
@media(hover:hover) and (pointer:fine){.plaza-net-lab .pn-card:hover:before{opacity:1}.plaza-net-lab .pn-card:hover .pn-night{opacity:1}[data-theme="dark"] .plaza-net-lab .pn-card:hover .pn-night{opacity:0}.plaza-net-lab :is(.pn-toggle,.pn-burger):hover{color:var(--pn-gold);background:rgba(178,148,95,.04)}}
.plaza-net-lab .pn-card:focus-within .pn-night{opacity:1}[data-theme="dark"] .plaza-net-lab .pn-card:focus-within .pn-night{opacity:0}
@media(max-width:1250px){.plaza-net-lab .header-inner{gap:14px}.plaza-net-lab .site-nav{gap:10px}.plaza-net-lab .site-nav .nav-links{gap:16px}.plaza-net-lab .header-actions{gap:8px}.plaza-net-lab .header-call{display:none!important}.plaza-net-lab .pn-card-title{font-size:17px}.plaza-net-lab .pn-caption{padding-inline:4px}.plaza-net-lab .pn-grid{gap:14px}}
